	msgsrv register(Client ref) {
		// Registration is implicit via knownrebecs; no dynamic list needed.
	}

	msgsrv ping() {
		// In Rebeca, 'sender' is not available; we model a nondeterministic client to pong.
		int choice;
		choice = ?(1,2,3,4,5);
